# authoritative source private and publish provenance/version history.

import hashlib

PROJECT_ID = "RABBITECH-PYBRICKS"
SECURITY_VERSION = "1.0.0"

# Expected SHA-256 values are generated by tools/update_integrity.py.
# Empty values deliberately fail closed until the manifest is generated.
EXPECTED = {
    "base.py": "",
    "memoria.py": "",
    "saida_1.py": "",
    "saida_2.py": "",
    "saida_3.py": "",
    "saida_4.py": "",
    "saida_5.py": "",
    "saida_6.py": "",
    "saida_7.py": "",
    "saida_8.py": "",
}

def _sha256(data):
    return hashlib.sha256(data).hexdigest()

def verify_sources(source_map):
    """Compare SHA-256 digests of supplied source bytes with the manifest."""
    for name, expected in EXPECTED.items():
        if not expected:
            print("INTEGRIDADE: manifesto nao configurado:", name)
            return False
        actual = _sha256(source_map.get(name, b""))
        if actual != expected:
            print("INTEGRIDADE: arquivo alterado:", name)
            return False
    return True

def show_identity():
    print(PROJECT_ID, SECURITY_VERSION)
